<?php
require_once __DIR__.'/includes/functions.php';require_customer();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('checkout.php');verify_csrf();$uid=(int)current_user()['id'];
$name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$pin=trim($_POST['pincode']??'');$method=$_POST['payment_method']??'cod';
if($name===''||$address===''||!preg_match('/^[0-9]{10,15}$/',$phone)||!in_array($method,['cod','upi'],true)){flash('Please check your delivery and payment details.','error');redirect('checkout.php');}
if(!valid_delivery_pin($conn,$pin)){flash('Sorry, delivery is not available for that PIN code.','error');redirect('checkout.php');}
try{$conn->begin_transaction();$s=$conn->prepare('SELECT c.product_id,c.quantity,p.name,p.price,p.stock,p.is_active FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=? FOR UPDATE');$s->bind_param('i',$uid);$s->execute();$items=$s->get_result()->fetch_all(MYSQLI_ASSOC);if(!$items)throw new RuntimeException('Your cart is empty.');$subtotal=0;foreach($items as $i){if(!$i['is_active']||(int)$i['quantity']>(int)$i['stock'])throw new RuntimeException('A product is out of stock or the available quantity changed.');$subtotal+=(float)$i['price']*(int)$i['quantity'];}$delivery=$subtotal>=499?0:30;$total=$subtotal+$delivery;$number='AM'.date('ymd').strtoupper(bin2hex(random_bytes(4)));$payStatus=$method==='upi'?'pending':'not_required';$status=$method==='upi'?'awaiting_payment_review':'placed';
$s=$conn->prepare('INSERT INTO orders(order_number,user_id,customer_name,phone,address,pincode,subtotal,delivery_charge,total,payment_method,payment_status,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->bind_param('sissssdddsss',$number,$uid,$name,$phone,$address,$pin,$subtotal,$delivery,$total,$method,$payStatus,$status);$s->execute();$orderId=$s->insert_id;
foreach($items as $i){$s=$conn->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity) VALUES(?,?,?,?,?)');$s->bind_param('iisdi',$orderId,$i['product_id'],$i['name'],$i['price'],$i['quantity']);$s->execute();$s=$conn->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$s->bind_param('iii',$i['quantity'],$i['product_id'],$i['quantity']);$s->execute();if($s->affected_rows!==1)throw new RuntimeException('Stock changed while ordering. Please try again.');}
$s=$conn->prepare('DELETE FROM cart_items WHERE user_id=?');$s->bind_param('i',$uid);$s->execute();$conn->commit();$_SESSION['last_order_id']=$orderId;redirect($method==='upi'?'payment.php?order='.$orderId:'my_orders.php');
}catch(Throwable $e){$conn->rollback();flash($e instanceof RuntimeException?$e->getMessage():'Unable to place the order. Please try again.','error');redirect('checkout.php');}
